import{_ as a,o as s,c as i,a4 as d}from"./chunks/framework.vNSRaLQv.js";const c=JSON.parse('{"title":"Linux 清理记录 — 血的教训","description":"","frontmatter":{"title":"Linux 清理记录 — 血的教训","date":"2026-07-18T00:00:00.000Z"},"headers":[],"relativePath":"posts/Linux清理记录.md","filePath":"posts/Linux清理记录.md"}'),e={name:"posts/Linux清理记录.md"};function n(r,t,l,h,p,o){return s(),i("div",null,[...t[0]||(t[0]=[d(`<h1 id="linux-清理记录-—-血的教训" tabindex="-1">Linux 清理记录 — 血的教训 <a class="header-anchor" href="#linux-清理记录-—-血的教训" aria-label="Permalink to &quot;Linux 清理记录 — 血的教训&quot;">​</a></h1><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>刚接触 Linux，以为删软件就像 Windows 一样，点卸载就完事了。 结果上次把 Firefox 和整个 KDE 桌面都删炸了 —— 明明没动它们，只是删了几个&quot;看着没用&quot;的东西。</p><h2 id="教训-linux-的依赖是链式的" tabindex="-1">教训：Linux 的依赖是链式的 <a class="header-anchor" href="#教训-linux-的依赖是链式的" aria-label="Permalink to &quot;教训：Linux 的依赖是链式的&quot;">​</a></h2><p>在 Linux 里，一个包可能被另一个包<strong>硬依赖（Depends）</strong>。 删掉它，依赖它的所有东西都会被一起删掉，哪怕你根本没想删那些。</p><p>例如：</p><ul><li><code>ibus-data</code> → <code>plasma-desktop</code> 硬依赖 → 删 ibus 会把桌面一起带走</li><li><code>pocketsphinx</code> → <code>libavfilter10</code> → <code>plasma-widgets-addons</code> → <code>plasma-desktop</code> → 删语音识别库会带走桌面</li><li><code>adwaita-icon-theme</code> → 会级联删掉 Firefox、fcitx5 输入法、GNOME 密钥环、最后整个桌面</li></ul><h2 id="关键工具-apt-get-dry-run" tabindex="-1">关键工具：<code>apt-get --dry-run</code> <a class="header-anchor" href="#关键工具-apt-get-dry-run" aria-label="Permalink to &quot;关键工具：\`apt-get --dry-run\`&quot;">​</a></h2><p>在动手之前，永远先模拟一遍：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">apt-get</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> --dry-run</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> purge</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> &lt;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">包</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">名</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">&gt;</span></span></code></pre></div><p>这会告诉你<strong>到底会删掉什么</strong>，而不会真的执行。 如果看到 <code>plasma-desktop</code>、<code>firefox-esr</code> 这些出现在列表里，立刻停手。</p><h2 id="什么是安全的" tabindex="-1">什么是安全的？ <a class="header-anchor" href="#什么是安全的" aria-label="Permalink to &quot;什么是安全的？&quot;">​</a></h2><p>只有<strong>推荐依赖（Recommends）</strong> 的包删了才安全。 可以用 <code>apt-cache depends &lt;包名&gt;</code> 查看依赖类型：</p><ul><li><code>Depends</code> = 硬依赖，删它会连带删掉依赖它的东西</li><li><code>Recommends</code> = 推荐依赖，可以安全删除</li><li><code>Suggests</code> = 建议，更安全</li></ul><h2 id="本次清理记录" tabindex="-1">本次清理记录 <a class="header-anchor" href="#本次清理记录" aria-label="Permalink to &quot;本次清理记录&quot;">​</a></h2><p>系统：Debian 13 (trixie) + KDE Plasma</p><h3 id="安全删掉的-仅删自己-不影响系统" tabindex="-1">安全删掉的（仅删自己，不影响系统） <a class="header-anchor" href="#安全删掉的-仅删自己-不影响系统" aria-label="Permalink to &quot;安全删掉的（仅删自己，不影响系统）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>大小</th><th>说明</th></tr></thead><tbody><tr><td>旧内核</td><td>111MB</td><td>当前运行的是新版，旧版无用</td></tr><tr><td>LibreOffice</td><td>~350MB</td><td>办公套件</td></tr><tr><td>GIMP</td><td>106MB</td><td>图像处理</td></tr><tr><td>Orca</td><td>16MB</td><td>屏幕朗读器（盲人用）</td></tr><tr><td>speech-dispatcher</td><td>28MB</td><td>语音合成（Orca 用的）</td></tr><tr><td>Cryfs / plasma-vault</td><td>58MB</td><td>加密文件夹</td></tr><tr><td>KMail / KOrganizer</td><td>65MB</td><td>邮件/日历</td></tr><tr><td>khelpcenter / docbook</td><td>15MB</td><td>帮助中心 / XML 文档格式</td></tr><tr><td>Kate</td><td>27MB</td><td>KDE 文本编辑器</td></tr><tr><td>Konqueror</td><td>12MB</td><td>上古浏览器</td></tr><tr><td>CUPS 打印机系统</td><td>~400MB</td><td>没有打印机就没用</td></tr><tr><td>Intel 显卡驱动</td><td>20MB</td><td>AMD 显卡用不上</td></tr><tr><td>杂项</td><td>~50MB</td><td>reportbug、nodejs-doc、字典、eject、akregator 等</td></tr><tr><td><strong>合计</strong></td><td><strong>~1.2GB</strong></td><td>8.7G → 7.5G</td></tr></tbody></table><h3 id="看起来能删但不能动的-会炸" tabindex="-1">看起来能删但不能动的（会炸） <a class="header-anchor" href="#看起来能删但不能动的-会炸" aria-label="Permalink to &quot;看起来能删但不能动的（会炸）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>包名</th><th>为什么不能删</th></tr></thead><tbody><tr><td>ibus-data / libibus-1.0-5</td><td>plasma-desktop 硬依赖</td></tr><tr><td>pocketsphinx</td><td>通过 ffmpeg 链到桌面</td></tr><tr><td>orca</td><td>之前以为不能删，后来发现只是 Recommends，已安全删除</td></tr><tr><td>adwaita-icon-theme</td><td>会连带 Firefox、fcitx5、桌面</td></tr><tr><td>breeze-wallpaper</td><td>会连带桌面</td></tr><tr><td>wacom 数位板驱动</td><td>被 libinput → plasma-desktop 硬依赖</td></tr><tr><td>desktop-base</td><td>会删 metapackage，但用户担心主题</td></tr><tr><td>gcc/g++/git/nodejs</td><td>开发工具，需要保留</td></tr></tbody></table><h3 id="安全验证命令" tabindex="-1">安全验证命令 <a class="header-anchor" href="#安全验证命令" aria-label="Permalink to &quot;安全验证命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 模拟删除，看会连带什么</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">apt-get</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> --dry-run</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> purge</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> &lt;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">包</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">名</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 查看谁依赖这个包</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">apt-cache</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> rdepends</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> --installed</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> &lt;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">包</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">名</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 查看依赖类型（Depends/Recommends/Suggests）</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">apt-cache</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> depends</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> &lt;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">包</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">名</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">&gt;</span></span></code></pre></div><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><ol><li><strong>永远先 <code>--dry-run</code></strong>，再动手</li><li><strong><code>apt-cache rdepends</code></strong> 看反向依赖，确认没人用这个包</li><li>只有 <strong>Recommends（推荐）</strong> 级别的可以安全删除</li><li><strong>Depends（硬依赖）</strong> 的删了就连锁反应</li><li>不确定就别动，Linux 的依赖树比想象中深得多</li></ol>`,24)])])}const g=a(e,[["render",n]]);export{c as __pageData,g as default};
